begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.reject(command text,expected text,label text) returns void language plpgsql as $$ begin begin execute command; raise exception 'accepted unexpectedly'; exception when others then if sqlerrm<>expected then raise; end if;end; perform pg_temp.assert(true,label);end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('r3.rev',(select coalesce(max(revision),0)::text from nutrition_guidance where relationship_id='40000000-0000-4000-8000-000000000001'),true);
select public.save_nutrition_guidance('b3000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001',current_setting('r3.rev')::int,current_date,'{"protein_g":120}','A practical guide');
select pg_temp.assert((public.save_nutrition_guidance('b3000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001',current_setting('r3.rev')::int,current_date,'{"protein_g":120}','A practical guide')).revision=current_setting('r3.rev')::int+1,'guidance retry preserves one immutable version');
select pg_temp.reject($q$select public.save_nutrition_guidance('b3000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001',current_setting('r3.rev')::int,current_date,'{}','Stale')$q$,'conflict','stale guidance cannot overwrite newer version');
select public.save_nutrition_guidance('b3000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001',current_setting('r3.rev')::int+1,current_date+1,'{}','Later guide');
select pg_temp.assert((select guidance='A practical guide' and targets->>'protein_g'='120' from nutrition_guidance where id='b3000000-0000-4000-8000-000000000001'),'later guidance preserves earlier targets and text');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.save_food('b3000000-0000-4000-8000-000000000003','Rice',100,'g','{"kcal":130,"protein_g":null}','Label',0);
select pg_temp.assert((public.save_food('b3000000-0000-4000-8000-000000000003','Rice',100,'g','{"kcal":130,"protein_g":null}','Label',0)).revision=1,'saved food retries preserve identity');
select public.save_meal('b3000000-0000-4000-8000-000000000004','40000000-0000-4000-8000-000000000001',current_date,'lunch','{"name":"Rice","quantity":150,"basis":100,"unit":"g","nutrients":{"kcal":130,"protein_g":null},"source":"Label","food_id":"b3000000-0000-4000-8000-000000000003"}',0);
select pg_temp.assert((public.save_meal('b3000000-0000-4000-8000-000000000004','40000000-0000-4000-8000-000000000001',current_date,'lunch','{"name":"Rice","quantity":150,"basis":100,"unit":"g","nutrients":{"kcal":130,"protein_g":null},"source":"Label","food_id":"b3000000-0000-4000-8000-000000000003"}',0)).revision=1,'meal retry does not duplicate actuals');
select public.save_food('b3000000-0000-4000-8000-000000000003','Rice changed',100,'g','{"kcal":140}','Updated label',1);
select pg_temp.assert((select nutrients->>'kcal'='130' and nutrients->'protein_g'='null'::jsonb from meal_entries where id='b3000000-0000-4000-8000-000000000004'),'food updates leave meal snapshot and unknown values intact');
select pg_temp.assert((public.save_meal('b3000000-0000-4000-8000-000000000004','40000000-0000-4000-8000-000000000001',current_date,'lunch','{"name":"Rice","quantity":150,"basis":100,"unit":"g","nutrients":{"kcal":130,"protein_g":null},"source":"Label","food_id":"b3000000-0000-4000-8000-000000000003"}',0)).revision=1,'meal retry uses explicit snapshot after catalog edit');
select pg_temp.reject($q$select public.save_meal('b3000000-0000-4000-8000-000000000004','40000000-0000-4000-8000-000000000001',current_date,'lunch','{"name":"Rice","quantity":160,"basis":100,"unit":"g","nutrients":{"kcal":130,"protein_g":null},"source":"Label","food_id":"b3000000-0000-4000-8000-000000000003"}',0)$q$,'conflict','stale meal correction is rejected');
select public.save_meal('b3000000-0000-4000-8000-000000000004','40000000-0000-4000-8000-000000000001',current_date,'lunch','{"name":"Rice","quantity":160,"basis":100,"unit":"g","nutrients":{"kcal":130,"protein_g":null},"source":"Label","food_id":"b3000000-0000-4000-8000-000000000003"}',1);
select pg_temp.assert((select quantity=160 and revision=2 from meal_entries where id='b3000000-0000-4000-8000-000000000004'),'meal correction updates one record');
select public.save_meal('b3000000-0000-4000-8000-000000000005',null,current_date,'lunch','{"name":"Rice","quantity":150,"basis":100,"unit":"g","nutrients":{"kcal":130,"protein_g":null},"source":"Label","food_id":"b3000000-0000-4000-8000-000000000003"}',0);
select pg_temp.reject($q$select public.save_nutrition_guidance('b3000000-0000-4000-8000-000000000008','40000000-0000-4000-8000-000000000001',0,current_date,'{}','Client edit')$q$,'forbidden','client cannot prescribe coach guidance');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.assert(exists(select 1 from meal_entries where id='b3000000-0000-4000-8000-000000000004') and not exists(select 1 from meal_entries where id='b3000000-0000-4000-8000-000000000005'),'coach sees explicitly shared meals only');
select pg_temp.assert(not exists(select 1 from saved_foods where id='b3000000-0000-4000-8000-000000000003'),'saved food library stays private');
select count(*) from public.publish_availability('b3000000-0000-4000-8000-000000000010',(current_date+300)::timestamp+interval '03:17','UTC',30,2,7,'R3 SQL appointment','Room A');
select pg_temp.assert((select count(*)=2 from public.publish_availability('b3000000-0000-4000-8000-000000000010',(current_date+300)::timestamp+interval '03:17','UTC',30,2,7,'R3 SQL appointment','Room A')),'availability retry creates exactly one series');
select pg_temp.reject($q$select * from public.publish_availability('b3000000-0000-4000-8000-000000000011',(current_date+300)::timestamp+interval '03:17','UTC',30,2,7,'R3 SQL appointment','Room A')$q$,'time_unavailable','coach cannot publish overlapping availability');
select pg_temp.reject($q$select public.availability_preview('2030-03-10 02:30','America/New_York',30,1,7)$q$,'invalid_local_time','nonexistent DST local time is rejected');
select pg_temp.assert(public.availability_preview('2030-11-03 01:30','America/New_York',30,1,7)->0->>'starts_at' like '2030-11-03T06:30:%','ambiguous DST time resolves consistently to standard time');
select pg_temp.reject($q$select public.availability_preview('2030-01-01','UTC',30,9,7)$q$,'invalid_availability','recurrence is bounded to eight');
select set_config('r3.slot',(select id::text from appointment_slots where series_id='b3000000-0000-4000-8000-000000000010' order by starts_at limit 1),true);
select set_config('r3.next',(select id::text from appointment_slots where series_id='b3000000-0000-4000-8000-000000000010' order by starts_at desc limit 1),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.book_appointment('b3000000-0000-4000-8000-000000000012','40000000-0000-4000-8000-000000000001',current_setting('r3.slot')::uuid);
select pg_temp.assert((public.book_appointment('b3000000-0000-4000-8000-000000000012','40000000-0000-4000-8000-000000000001',current_setting('r3.slot')::uuid)).revision=1,'booking retry creates one appointment');
select pg_temp.reject($q$select public.book_appointment('b3000000-0000-4000-8000-000000000013','40000000-0000-4000-8000-000000000001',current_setting('r3.slot')::uuid)$q$,'time_unavailable','already booked slot rejects another booking');
select pg_temp.reject($q$select public.change_appointment('b3000000-0000-4000-8000-000000000012',1,'attended')$q$,'forbidden','client cannot mark appointment attendance');
select public.change_appointment('b3000000-0000-4000-8000-000000000012',1,'reschedule',current_setting('r3.next')::uuid,'New time');
select pg_temp.assert((select state='open' from appointment_slots where id=current_setting('r3.slot')::uuid) and (select state='booked' from appointment_slots where id=current_setting('r3.next')::uuid),'reschedule atomically releases old slot and reserves new slot');
select pg_temp.assert((public.change_appointment('b3000000-0000-4000-8000-000000000012',1,'reschedule',current_setting('r3.next')::uuid,'New time')).revision=2,'reschedule retry preserves revision');
select pg_temp.reject($q$select public.change_appointment('b3000000-0000-4000-8000-000000000012',1,'cancelled')$q$,'conflict','stale cancellation is rejected');
select public.change_appointment('b3000000-0000-4000-8000-000000000012',2,'cancelled',null,'Cannot make it');
select pg_temp.assert((public.change_appointment('b3000000-0000-4000-8000-000000000012',2,'cancelled',null,'Cannot make it')).revision=3,'cancellation retry is idempotent');
select pg_temp.assert((select state='open' from appointment_slots where id=current_setting('r3.next')::uuid),'cancellation restores available time');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.withdraw_availability(current_setting('r3.next')::uuid);
select pg_temp.assert((select state='withdrawn' from appointment_slots where id=current_setting('r3.next')::uuid),'coach can withdraw unbooked availability');
reset role;
insert into public.appointment_slots(id,series_id,coach_id,starts_at,ends_at,local_start,timezone,title,location,state) values('b3000000-0000-4000-8000-000000000014','b3000000-0000-4000-8000-000000000014','10000000-0000-4000-8000-000000000001',now()-interval '2 days',now()-interval '2 days'+interval '30 minutes',(now()-interval '2 days')::timestamp,'UTC','Past meeting','Room A','booked');
insert into public.appointments(id,relationship_id,slot_id,starts_at,ends_at,title,location,timezone) select 'b3000000-0000-4000-8000-000000000015','40000000-0000-4000-8000-000000000001',id,starts_at,ends_at,title,location,timezone from public.appointment_slots where id='b3000000-0000-4000-8000-000000000014';
set local role authenticated;
select set_config('r3.sessions',(select count(*)::text from public.sessions),true);
select public.change_appointment('b3000000-0000-4000-8000-000000000015',1,'attended',null,'Discussed next month');
select pg_temp.assert((public.change_appointment('b3000000-0000-4000-8000-000000000015',1,'attended',null,'Discussed next month')).revision=2,'attendance retry changes no additional revision');
select pg_temp.assert((select count(*)::text=current_setting('r3.sessions') from public.sessions),'appointment attendance never creates training completion');
select public.register_resource('b3000000-0000-4000-8000-000000000020','R3 private guide','guide.txt','text/plain',12);
select pg_temp.assert((public.register_resource('b3000000-0000-4000-8000-000000000020','R3 private guide','guide.txt','text/plain',12)).revision=1,'resource registration retry preserves path');
select pg_temp.reject($q$select public.finish_resource('b3000000-0000-4000-8000-000000000020')$q$,'upload_incomplete','resource cannot be finalized without stored bytes');
select pg_temp.reject($q$select public.register_resource('b3000000-0000-4000-8000-000000000021','Bad','../bad.txt','text/plain',1)$q$,'invalid_file','file names cannot contain path traversal');
select pg_temp.reject($q$select public.delete_my_account('DELETE')$q$,'file_cleanup_required','account deletion waits for file cleanup');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'rafik-private',object_path,'{"size":12,"mimetype":"text/plain"}'::jsonb from resources where id='b3000000-0000-4000-8000-000000000020';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.finish_resource('b3000000-0000-4000-8000-000000000020');
select pg_temp.assert((public.finish_resource('b3000000-0000-4000-8000-000000000020')).revision=2,'finalization replay does not mutate ready file');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert(not exists(select 1 from resources where id='b3000000-0000-4000-8000-000000000020'),'unshared resource is invisible to client');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.share_resource('b3000000-0000-4000-8000-000000000020','40000000-0000-4000-8000-000000000001',true);
select public.share_resource('b3000000-0000-4000-8000-000000000020','40000000-0000-4000-8000-000000000001',true);
select pg_temp.assert((select count(*)=1 from resource_shares where resource_id='b3000000-0000-4000-8000-000000000020'),'share retry creates one relationship permission');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert(exists(select 1 from resources where id='b3000000-0000-4000-8000-000000000020') and exists(select 1 from storage.objects where name like '%b3000000-0000-4000-8000-000000000020'),'shared resource metadata and storage policy agree');
select public.send_message('b3000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000001','Read this guide',null,null,'b3000000-0000-4000-8000-000000000020');
select pg_temp.assert((public.send_message('b3000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000001','Read this guide',null,null,'b3000000-0000-4000-8000-000000000020')).resource_id='b3000000-0000-4000-8000-000000000020','shared resource can be attached with stable message ID');
select pg_temp.reject($q$select public.retire_resource('b3000000-0000-4000-8000-000000000020',2)$q$,'forbidden','recipient cannot retire owner file');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.assert(not exists(select 1 from resources where id='b3000000-0000-4000-8000-000000000020'),'unrelated client cannot read shared file');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.share_resource('b3000000-0000-4000-8000-000000000020','40000000-0000-4000-8000-000000000001',false);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert(not exists(select 1 from resources where id='b3000000-0000-4000-8000-000000000020') and not exists(select 1 from storage.objects where name like '%b3000000-0000-4000-8000-000000000020'),'revoking share removes metadata and storage read access');
select pg_temp.reject($q$select public.send_message('b3000000-0000-4000-8000-000000000023','40000000-0000-4000-8000-000000000001','Read this guide',null,null,'b3000000-0000-4000-8000-000000000020')$q$,'resource_unavailable','revoked file cannot be attached to new messages');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.retire_resource('b3000000-0000-4000-8000-000000000020',2);
select pg_temp.reject($q$select public.remove_resource_record('b3000000-0000-4000-8000-000000000020')$q$,'file_cleanup_required','metadata cannot be removed while stored object remains');
rollback;
